def seed_states(apps, schema_editor):
    """Mavjud kompaniyalarga standart statuslar va buyurtmalarga ularni biriktirish (ma'lumot o'chirilmaydi)."""
    Order = apps.get_model("orders", "Order")
    OrderState = apps.get_model("orders", "OrderState")
    company_ids = set(Order._base_manager.values_list("company_id", flat=True).distinct())
    for cid in company_ids:
        by_kind = {}
        for i, (kind, name, color) in enumerate(DEFAULTS):
            st = OrderState._base_manager.create(company_id=cid, kind=kind, name=name, color=color, position=(i + 1) * 10)
            by_kind[kind] = st
        for kind, st in by_kind.items():
            Order._base_manager.filter(company_id=cid, status=kind).update(state=st)


